			DEF(["Điều kiện → hành động", "IF (một điều kiện), IFS hoặc IF lồng nhau (nhiều bậc); COUNTIF/SUMIF cho đếm/tổng theo điều kiện."], ["Tìm giá trị theo khóa", "VLOOKUP nhìn sang phải và dễ tìm 'gần đúng' nếu quên đối số thứ tư; INDEX–MATCH nhìn được cả bên trái."], ["Tóm tắt nhiều dòng", "PivotTable gom dòng theo nhóm và tính tổng/trung bình, không tạo ra dữ liệu mới."], ["Hình dung xu hướng", "Cột để so các nhóm; đường để theo thời gian."]),
			H("2. Lỗi thường gặp"),
			UL("Quên $ nên địa chỉ trượt khi kéo công thức.", "Ô trống bị hiểu là 0 khi tính trung bình.", "VLOOKUP trả #N/A vì khóa có dấu cách thừa hoặc kiểu số/chữ khác nhau."),
			GO("xl-lock", "xl-if", "xl-look", "xa-match", "xl-pivot", "xa-count")
